		var _R0 float64
		switch BodyDoji_rangeType {
		case 0:
			_R0 = math.Abs(inClose - inOpen)
		case 1:
			_R0 = inHigh - inLow
		case 2:
			_R0 = (inHigh - selF(inClose >= inOpen, inClose, inOpen)) + (selF(inClose >= inOpen, inOpen, inClose) - inLow)
		}
